    public static final String ENTRY_DATE = "entry-date";

    /** The grace days (a whole number; blank: off): when the sheet's today changes, an open period
     *  whose to-date plus them is before the new today is closed. */
    public static final String GRACE_DAYS = "grace-days";

    /** The escalation gap (a whole number of days; blank: off; not dated): reminding a claim whose previous
     *  reminder was at least that many days before the sheet's today escalates it, once per claim. */
    public static final String ESCALATE_AFTER = "escalate-after";

    /** The review SLA (a whole number of days; blank: none; not dated): a REVIEW claim whose review day
     *  (the sheet's today when it went to REVIEW) plus them is before the sheet's today is late. */
    public static final String REVIEW_SLA = "review-sla";

    /** The maximum of open claims per person (a whole number; blank: none; not dated): opening a claim
     *  is refused when its person already has that many OPEN or PENDING claims. */
    public static final String MAX_OPEN = "max-open";

    /** The mid score threshold (a whole number; blank: none; not dated): while both score thresholds are
     *  set, a person whose score is at or above it, and below the high one, is in the MID band. */
    public static final String SCORE_MID = "score-mid";

    /** The high score threshold (a whole number; blank: none; not dated): while both score thresholds are
     *  set, a person whose score is at or above it is in the HIGH band. */
    public static final String SCORE_HIGH = "score-high";

    /** The score log (on or blank; not dated): while on, changing the sheet's today records, before the
     *  SNAPSHOT lines, a SCORE line per person with their score on the day being left. */
    public static final String SCORE_LOG = "score-log";

